from collections import deque

def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    y,x=q.pop(); cells.append((y,x))
                    for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx] and (ny,nx) not in seen:
                            seen.add((ny,nx));q.append((ny,nx))
                comps.append(cells)
    return comps

def transform(grid):
    comps=components(grid)
    boxes=[]
    for cells in comps:
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        boxes.append((min(rs),max(rs),min(cs),max(cs)))
    if len(boxes)!=2: raise ValueError((len(boxes),boxes))
    boxes.sort(key=lambda b:(b[2],b[0]))
    (r0a,r1a,c0a,c1a),(r0b,r1b,c0b,c1b)=boxes
    ha,wa=r1a-r0a+1,c1a-c0a+1; hb,wb=r1b-r0b+1,c1b-c0b+1
    if (ha,wa)!=(hb,wb): raise ValueError(((ha,wa),(hb,wb),boxes))
    diffs=[]
    for r in range(ha):
        for c in range(wa):
            if grid[r0a+r][c0a+c] != grid[r0b+r][c0b+c]:
                diffs.append((r,c))
    if not diffs: return [[0]]
    rmin=min(r for r,c in diffs);rmax=max(r for r,c in diffs);cmin=min(c for r,c in diffs);cmax=max(c for r,c in diffs)
    return [[8 if (r,c) in set(diffs) else 0 for c in range(cmin,cmax+1)] for r in range(rmin,rmax+1)]
